solution:
def double(x):
    return x * 2

def square(x):
    return x * x

def dec(x):
    return x - 1

def apply_twice(f, x):
    return f(f(x))

name, x = input().split()
x = int(x)
spells = {"double": double, "square": square, "dec": dec}
print(apply_twice(spells[name], x))
